@Experimental
interface RowCursor extends AutoCloseable {
	boolean next() throws IOException;

	/** Facts belong to this actual producer, not to a logical plan that another strategy may lower differently. */
	default NativeExpressionDomainPolicy.Input expressionInput() {
		return null;
	}

	@Override
	void close();
}

@Experimental
final class EmptyPlan implements SlotPlan {
	static final EmptyPlan INSTANCE = new EmptyPlan();

	@Override
	public RowCursor open(RowState row) {
		return EmptyCursor.INSTANCE;
	}

	@Override
	public long producedMask() {
		return 0L;
	}

	@Override
	public LmdbNativeWork estimateWork(RowState row, long boundMask) {
		return LmdbNativeWork.ZERO;
	}
}

@Experimental
final class SingletonPlan implements SlotPlan {
	static final SingletonPlan INSTANCE = new SingletonPlan();

	@Override
	public RowCursor open(RowState row) {
		return new SingletonCursor();
	}

	@Override
	public long producedMask() {
		return 0L;
	}

	@Override
	public LmdbNativeWork estimateWork(RowState row, long boundMask) {
		// Emits the entry row unchanged: no seek, no scan.
		return LmdbNativeWork.ZERO;
	}
}

@Experimental
final class EmptyCursor implements RowCursor {
	static final EmptyCursor INSTANCE = new EmptyCursor();

	@Override
	public boolean next() {
		return false;
	}

	@Override
	public void close() {
	}
}

@Experimental
final class SingletonCursor implements RowCursor {
	boolean done;

	@Override
	public boolean next() {
		if (done) {
			return false;
		}
		done = true;
		return true;
	}

	@Override
	public void close() {
		done = true;
	}
}
